public class Xbonacci {

  public double[] tribonacci(double[] s, int n) {
    //base case
        if(n == 0) {
            return new double[0];
        }
        double[] arr = new double[n];
        for (int i = 0; i < n; i++){
            if(i == 0 || i == 1 || i == 2){
                arr[i] = s[i];
            }
            else{
                arr[i] = arr[i-1] + arr[i-2] + arr[i-3];
            }
        }
        return arr;
    }
}
