public class Xbonacci {

  public double[] xbonacci(double[] signature, int n) {
        // hackonacci me
        double[] arr = new double[n];
        for (int i = 0; i < n; i++){
            if (i >= 0 && i < signature.length){
                arr[i] = signature[i];
            }
            else {
                for (int j = 1; j <= signature.length; j++){
                    arr[i] += arr[i-j];
                }
            }
        }
        return arr;

    }
}
